    { zone = 100, name = 'New Year Greeter', label = 'New Year 2010', model = 82, pos = { -379.047, -35.841, 140.833 }, lines = {
        'Roar! Groar!',
        'Roar!',
        'Grrr...',
        'Happy-wappy new year to you, [sir/ma\'am]! And apparently...commiserations!',
        'Happy-wappy new year to you, [sir/ma\'am]! And apparently...congratulations!',
        'Oooh, you\'re sure to like this! He says, Beforrre me stands a person-werson who\'ll be swimming in fantarustic forrrtune this year!',
        'Oooh, nice! He says, You\'re going be in for a grrreataru year with oodles of elation!',
        'That was, Justaru the rrright amount of happiness is going to be coming your way!',
        'That translates to, You win some, you lose some. But on the whole, there\'s no rrreason-weason why you should be pessimistic!',
        'Uh oh! That was, You\'ll need to dig deepy-weep for some luck of your own this yearrr!',
        'Hrrrm... Rather than interpretaru that, let me just say, whatever happens this year, always rememberrr to keep your chinny-win up!',
        'A fabulous-wabulous yearrr to you, adventurer!',
    } },
